cat > /etc/nginx/sites-available/secure-8443 <<'ANTRIEB_NGINX_EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1;

    ssl_certificate /etc/ssl/certs/secure-web.crt;
    ssl_certificate_key /etc/ssl/private/secure-web.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    root /var/www/secure-8443;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
ANTRIEB_NGINX_EOF
chown root:root /etc/nginx/sites-available/secure-8443
chmod 0644 /etc/nginx/sites-available/secure-8443
printf 'nginx site written\n'

